<div class="d-flex justify-content-between mb-3"><div><h2 class="fw-bold"><?=e($sale['sale_no'])?></h2><div class="text-muted"><?=e($sale['created_at'])?> · <?=e($sale['cashier'])?></div></div><div><a class="btn btn-outline-dark" href="<?=e(base_url('sales/'.$sale['id'].'/receipt'))?>" target="_blank">Ticket</a> <a class="btn btn-outline-dark" href="<?=e(base_url('sales'))?>">Retour</a></div></div><div class="row g-3"><div class="col-lg-8"><div class="km-card p-3"><table class="table align-middle"><thead><tr><th>Produit</th><th>Qté</th><th>Prix</th><th>Total</th><th>Retour</th></tr></thead><tbody><?php foreach($sale['items'] as $i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['quantity'])?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['subtotal'])?></td><td><?php if($sale['status']!=='CANCELLED'):?><form class="d-flex gap-1" method="post" action="<?=e(base_url('sales/'.$sale['id'].'/return'))?>"><?=csrf_field()?><input type="hidden" name="sale_item_id" value="<?=$i['id']?>"><input class="form-control form-control-sm" style="width:75px" type="number" step="0.001" min="0.001" max="<?=$i['quantity']?>" name="quantity" value="1"><input class="form-control form-control-sm" name="reason" placeholder="Motif"><button class="btn btn-sm btn-outline-danger">Retour</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><div class="text-end fs-4 fw-bold">Total: <?=money($sale['total'])?></div></div><div class="km-card p-3 mt-3"><h5>Retours</h5><?php if(!$returns):?><div class="text-muted">Aucun retour.</div><?php endif;?><?php foreach($returns as $r):?><div class="border-bottom py-2 d-flex justify-content-between"><span><?=e($r['return_no'])?> · <?=e($r['reason'])?></span><strong><?=money($r['amount'])?></strong></div><?php endforeach;?></div></div><div class="col-lg-4"><div class="km-card p-4"><h5>État de la vente</h5><div class="fs-4 fw-bold mb-3"><?=e($sale['status'])?></div><?php if($sale['status']==='COMPLETED'):?><form method="post" action="<?=e(base_url('sales/'.$sale['id'].'/cancel'))?>"><?=csrf_field()?><label class="form-label">Motif d'annulation</label><textarea class="form-control" name="reason" required></textarea><button class="btn btn-outline-danger w-100 mt-2" data-confirm="Annuler toute la vente et restaurer le stock ?">Annuler la vente</button></form><?php endif;?></div></div></div>
